import React, { Component } from 'react';
import { CButton } from '@coreui/react';
import { requestHeaderGETWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import { Table } from 'react-bootstrap';

const FILE_NAME = "ListInternetTenants.js";

class ListInternetTenants extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            internetTenants: [],
        };
    }

    componentDidMount() {
        document.title = "Internet Tenants";
        this.fetchInternetTenants();
    }

    fetchInternetTenants = () => {
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/internet-tenant/list';

        this.setState({ isLoaded: false });

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchInternetTenants", "SUCCESS", "result", result);
            this.setState({ isLoaded: true, internetTenants: result.data || [] });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchInternetTenants", "ERROR", "error", error);
            this.setState({ isLoaded: true });
        });
    }

    render() {
        const { isLoaded, internetTenants } = this.state;

        if (!isLoaded) return <Loading />;

        return (
            <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                    <h2>🌐 Internet Tenants ({internetTenants.length})</h2>
                    <div style={{ display: 'flex', gap: '8px' }}>
                        <CButton color="secondary" onClick={this.fetchInternetTenants} title="Refresh">🔄</CButton>
                        <a href="#/internet-tenant/create">
                            <CButton color="success">+ Create a new Internet Tenant</CButton>
                        </a>
                    </div>
                </div>

                <Table striped bordered hover style={{ width: '100%' }}>
                    <thead>
                        <tr>
                            <th>#</th>
                            <th>Name</th>
                            <th>Base Domain</th>
                            <th>Created (yyyy-mm-dd)</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {internetTenants.length === 0 ? (
                            <tr><td colSpan="5" style={{ textAlign: 'center', color: '#888' }}>No internet tenants found</td></tr>
                        ) : (
                            internetTenants.map(tenant => (
                                <tr key={'internet-tenant-' + tenant.id}>
                                    <td>{tenant.id}</td>
                                    <td><strong>{tenant.name}</strong></td>
                                    <td>{tenant.baseDomain}</td>
                                    <td>{tenant.createdAt ? new Date(tenant.createdAt).toISOString().split('T')[0] : '—'}</td>
                                    <td>
                                        <CButton color="info" size="sm" onClick={() => window.open('#/internet-tenant/' + tenant.id, '_blank')}>
                                            View ↗
                                        </CButton>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </Table>
            </div>
        );
    }
}

export default ListInternetTenants;
